  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C37"],
      "claim": "Norethisterone, the highest-transfer analogue, has an absolute oral bioavailability of 64% in healthy volunteers; its fused polycyclic steroid-like scaffold with ketone and hydroxyl groups supports high F for the similarly fused morphinan query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Etonogestrel (3-keto-desogestrel) has an absolute oral bioavailability of 76.1 ± 22.5% in healthy female volunteers, providing a second steroid-like fused-ring analogue that independently supports high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "LSD, a basic-amine-containing polycyclic alkaloid, has an absolute oral bioavailability of 80% in humans; the shared basic amine and polycyclic architecture support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Tramadol, which contains a basic dimethylamino group and a methoxyphenyl ring similar to the query's N-methyl and methoxy features, has a mean oral bioavailability of 68% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Eplerenone, a steroid-like molecule with ketone and ester groups, has an oral bioavailability of about 98% in humans, further supporting high F for the fused-ring query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values between 46% and 98%, uniformly above the 20% threshold; the query's morphinan scaffold with a basic amine and moderate lipophilicity is consistent with these high-F analogues. Therefore predict high.",
